Lemma whole_byte_array_to_uninit288
 (Sigma : gFunctors) (islaG0 : islaG Sigma)
 (address : Z) (fraction : dfrac) (bytes : list (bv 8)) (count : nat) :
 List.length bytes = count ->
 @bi_entails (uPredI (iResUR Sigma))
   (@mem_mapsto_array Sigma (@islaG_gen_heapG Sigma islaG0) 8 address fraction bytes)
   (@mem_mapsto_uninit Sigma (@islaG_gen_heapG Sigma islaG0) address fraction (Z.of_nat count)).
Proof.
 intros Hlength.
 iIntros "Hbytes".
 iDestruct (@mem_mapsto_byte_array_to_mapsto_len Sigma islaG0 count address fraction bytes Hlength
   with "Hbytes") as "Hword".
 iDestruct (@mem_mapsto_mapsto_to_uninit Sigma (@islaG_gen_heapG Sigma islaG0)
   address fraction (8 * N.of_nat count)%N
   (Z_to_bv (8 * N.of_nat count)%N (little_endian_to_bv 8 bytes))
   with "Hword") as "Hstack".
 iEval (rewrite N.mul_comm N.div_mul; [rewrite nat_N_Z | done]) in "Hstack".
 iExact "Hstack".
Qed.
